import * as THREE from './three.module.js';
import {COURT as C,wallX} from './court-geometry.js';
export const WINDOW_LAYOUTS={
 '2':{centres:[-8,1,10],halfWidth:1.55,bottom:5.35,top:6.65,panes:2},
 '4':{centres:[-9,-1,7,13.5],halfWidth:1.02,bottom:4.45,top:6.85,panes:3},
 '7':{centres:[-10,-5,0,5,10,15],halfWidth:.64,bottom:5.05,top:7.15,panes:2},
 '5':{centres:[-9.5,-4,2,8,14],halfWidth:.63,bottom:4.75,top:6.15,porthole:true}
};
// Project the actual circular aperture through the same parallel sunlight as the windows.
export function portholeLightGeometry(x,y,z,radius=.48){const geometry=new THREE.CircleGeometry(radius,64),position=geometry.attributes.position;for(let i=0;i<position.count;i++){const Y=y+position.getY(i),Z=z+position.getX(i);position.setXYZ(i,x-Y/1.1,.013,Z+Y*.45/1.1);}position.needsUpdate=true;geometry.computeVertexNormals();return geometry;}
// Window geometry is independent of the court's playing surfaces and collision model.
export function buildWindowScheme(id,{scene,box,surface,upper,trim,wood,material}){const layout=WINDOW_LAYOUTS[id],group=new THREE.Group();group.userData.windowScheme=id;scene.add(group);const add=o=>{group.add(o);return o;},rear=C.halfLength+(C.halfLength-C.endRoofInner),low=-C.halfLength;
 const skin=(profile,start,end)=>{const panel=(a,b,y0,y1)=>{if(b<=a)return;const edges=[a,...[C.tambourEnd,C.tambourStart].filter(z=>z>a&&z<b),b];for(let i=0;i<edges.length-1;i++){const A=edges[i],B=edges[i+1];add(surface([[profile(A),y0,A],[profile(B),y0,B],[profile(B),y1,B],[profile(A),y1,A]],upper));}};panel(start,end,3.4,layout.bottom);panel(start,end,layout.top,7.6);let edge=start;for(const z of layout.centres){panel(edge,z-layout.halfWidth,layout.bottom,layout.top);edge=z+layout.halfWidth;}panel(edge,end,layout.bottom,layout.top);};
 skin(wallX,low,rear);if(id==='5')skin(()=>C.roofOuterX,low,rear);
 const sides=id==='5'?[1,-1]:[1];for(const side of sides)for(const z of layout.centres){const x=side>0?wallX(z):C.roofOuterX,h=layout.top-layout.bottom,y=(layout.top+layout.bottom)/2,w=layout.halfWidth;const glass=new THREE.MeshBasicMaterial({color:id==='5'?'#b6d5dc':'#e4f0ee',side:THREE.DoubleSide});
 if(layout.porthole){const surround=new THREE.Shape();surround.moveTo(-w,-h/2);surround.lineTo(w,-h/2);surround.lineTo(w,h/2);surround.lineTo(-w,h/2);surround.closePath();const hole=new THREE.Path();hole.absarc(0,0,.48,0,Math.PI*2,true);surround.holes.push(hole);const fill=new THREE.Mesh(new THREE.ShapeGeometry(surround,32),upper);fill.material=upper.clone();fill.material.side=THREE.DoubleSide;fill.castShadow=true;fill.receiveShadow=true;fill.rotation.y=-Math.PI/2;fill.position.set(x,y,z);add(fill);
 const pane=new THREE.Mesh(new THREE.CircleGeometry(.48,48),glass);pane.rotation.y=-Math.PI/2;pane.position.set(x,y,z);pane.castShadow=false;add(pane);const steel=new THREE.MeshStandardMaterial({color:'#bec9cc',metalness:.65,roughness:.28});const ring=new THREE.Mesh(new THREE.TorusGeometry(.49,.038,10,48),steel);ring.rotation.y=-Math.PI/2;ring.position.set(x-side*.025,y,z);add(ring);for(let a=0;a<Math.PI*2;a+=Math.PI/4){const bolt=new THREE.Mesh(new THREE.SphereGeometry(.016,10,8),steel);bolt.position.set(x-side*.058,y+Math.sin(a)*.49,z+Math.cos(a)*.49);add(bolt);}
 }else{const pane=surface([[x,layout.bottom,z-w],[x,layout.bottom,z+w],[x,layout.top,z+w],[x,layout.top,z-w]],glass);pane.castShadow=false;add(pane);for(const Z of [z-w,z+w])add(box(.09,h+.15,.09,x,y,Z,wood));for(const Y of [layout.bottom-.04,layout.top+.04])add(box(.12,.10,w*2+.18,x,Y,z,wood));for(let n=1;n<layout.panes;n++)add(box(.09,h,.055,x-side*.025,y,z-w+n*(2*w/layout.panes),trim));if(id==='2')add(box(.09,.055,2*w,x-side*.03,layout.top-.30,z,trim));}
 // Project a few broad clear-light patches from each distinct opening.
 if(side>0&&Math.abs(z)+layout.top*.45/1.1<C.endRoofInner){const bottom=layout.porthole?y-.3:layout.bottom+.1,top=layout.porthole?y+.3:layout.top-.1;const project=(Y,Z)=>[x-Y/1.1,.013,Z+Y*.45/1.1];const m=new THREE.MeshBasicMaterial({color:'#fff6da',transparent:true,opacity:id==='5'?.08:.10,depthWrite:false,side:THREE.DoubleSide});const patch=layout.porthole?new THREE.Mesh(portholeLightGeometry(x,y,z),m):surface([project(bottom,z-w*.8),project(bottom,z+w*.8),project(top,z+w*.8),project(top,z-w*.8)],m);patch.userData.lightShape=layout.porthole?'ellipse':'rectangle';patch.castShadow=false;add(patch);}}
 group.visible=false;return group;}
